// ─── File: LoadBalancerDemo.java ───
package com.bank.lb;

import java.util.logging.*;

public class LoadBalancerDemo {
    private static final Logger log = Logger.getLogger("LB");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BackendPool pool = new BackendPool();
        pool.add(new Backend("transfer-1"));
        pool.add(new Backend("transfer-2"));
        pool.add(new Backend("transfer-3"));
        LoadBalancer lb = new LoadBalancer(pool);

        // Round-robin distributes evenly across healthy servers
        log.info("Round-robin distribution:");
        for (int i = 0; i < 5; i++) {
            String s = lb.roundRobin();
            log.info(() -> "  routed to " + s);
        }

        // Health check marks transfer-2 down → it is skipped
        HealthChecker checker = new HealthChecker(pool);
        checker.markUnhealthy("transfer-2");
        log.info("After transfer-2 unhealthy:");
        for (int i = 0; i < 3; i++) {
            String s = lb.roundRobin();
            log.info(() -> "  routed to " + s);
        }

        // Least-connections picks the least busy server
        pool.get("transfer-1").setActiveConnections(10);
        pool.get("transfer-3").setActiveConnections(2);
        log.info(() -> "Least-connections -> " + lb.leastConnections());

        // IP hash gives sticky routing for a client
        log.info(() -> "IP hash for 10.0.0.5 -> " + lb.ipHash("10.0.0.5"));

        // L7 path routing
        log.info(() -> "/api/statements -> pool " + lb.routeL7("/api/statements"));
    }
}

