```java
// ─── File: BackendPool.java ───
package com.bank.lb;

import java.util.*;
import java.util.stream.*;

public class BackendPool {
    private final Map<String, Backend> backends = new LinkedHashMap<>();
    public void add(Backend b) { backends.put(b.getId(), b); }
    public Backend get(String id) { return backends.get(id); }
    public List<Backend> healthy() {
        return backends.values().stream().filter(Backend::isHealthy).collect(Collectors.toList());
    }
}
```

