package com.bank.lb;

import java.util.logging.*;

public class HealthChecker {
    private static final Logger log = Logger.getLogger("LB");
    private final BackendPool pool;
    public HealthChecker(BackendPool pool) { this.pool = pool; }

    // in production this probes GET /health periodically
    public void markUnhealthy(String id) {
        pool.get(id).setHealthy(false);
        log.warning(() -> "health check FAILED for " + id + ", removed from rotation");
    }
    public void markHealthy(String id) {
        pool.get(id).setHealthy(true);
        log.info(() -> "health check OK for " + id + ", back in rotation");
    }
}
```

```java
// ─── File: LoadBalancer.java ───
package com.bank.lb;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class LoadBalancer {
    private final BackendPool pool;
    private final AtomicInteger counter = new AtomicInteger();

    public LoadBalancer(BackendPool pool) { this.pool = pool; }

    public String roundRobin() {
        List<Backend> healthy = pool.healthy();
        return healthy.get(Math.abs(counter.getAndIncrement()) % healthy.size()).getId();
    }
    public String leastConnections() {
        return pool.healthy().stream()
            .min(Comparator.comparingInt(Backend::getActiveConnections))
            .map(Backend::getId).orElseThrow();
    }
    public String ipHash(String clientIp) {
        List<Backend> healthy = pool.healthy();
        return healthy.get(Math.abs(clientIp.hashCode()) % healthy.size()).getId();
    }
    // L7: route by request path to a logical pool
    public String routeL7(String path) {
        if (path.startsWith("/api/transfers")) return "transfer-pool";
        if (path.startsWith("/api/statements")) return "statement-pool";
        return "default-pool";
    }
}
```
